-- PREREQ for the develop release (read-only). Generated by scripts/release/build-release-gates.cjs.
-- Stops (ON_ERROR_STOP) unless develop is exactly the reconciled pre-release state the rehearsal used:
-- the 4 functions the release replaces have the recorded bodies, none of the release objects exists,
-- and no job uses the cash collection mode.
\set ON_ERROR_STOP 1
BEGIN READ ONLY;
DO $pre$
DECLARE r record; v text; bad text := '';
BEGIN
 FOR r IN SELECT * FROM (VALUES
  ('public.driver_cash_credit_status_v1f(p_driver_id uuid)','064ec2d40d9339a1b685571abaab9262'),
  ('public.enforce_job_payment_eligibility()','54905ee2c1c71638c176efed1569e27a'),
  ('public.enforce_ride_cash_credit_v1e()','28a630e2c5cfe42b859125b8f75cfd5e'),
  ('public.reserve_cash_job_credit_v1e(p_job_id uuid, p_driver_id uuid)','94ca1388576d2028e990d662def53498')) t(sig,md5) LOOP
  SELECT md5(replace(pg_get_functiondef(p.oid),chr(13),'')) INTO v FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' = r.sig;
  IF v IS DISTINCT FROM r.md5 THEN bad := bad || format(E'\n  replaced function differs from the reconciled state: %s (found %s)', r.sig, coalesce(v,'MISSING')); END IF;
 END LOOP;
 FOR r IN SELECT * FROM (VALUES
  ('public.activate_cash_ride_v1e(p_job_id uuid, p_customer_id uuid, p_provider text, p_provider_payment_reference text, p_amount_minor bigint, p_currency text)'),
  ('public.cancel_job_with_actor(p_job_id uuid, p_reason text, p_actor uuid, p_actor_role text)'),
  ('public.cancellation_fee_quote(p_job uuid, p_actor_role text, p_at timestamp with time zone)'),
  ('public.cash_acquisition_allowed_v1e(j jobs)'),
  ('public.cash_ride_acquirable_v1e(j jobs)'),
  ('public.cash_service_enabled_v1e(p_slug text, p_country text, p_currency text)'),
  ('public.complete_cash_ride_v1e(p_job_id uuid, p_driver_id uuid, p_metadata jsonb)'),
  ('public.driver_cash_credit_market_enabled_v1e(p_country text, p_currency text)'),
  ('public.driver_offer_metrics_v2(p_driver uuid, p_since timestamp with time zone)'),
  ('public.record_negotiated_assignment(p_job uuid, p_driver uuid)'),
  ('public.set_cancellation_policy_enabled(p_policy uuid, p_tenant uuid, p_enabled boolean)')) t(sig) LOOP
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' = r.sig) THEN bad := bad || format(E'\n  already exists: %s', r.sig); END IF;
 END LOOP;
 IF to_regclass('public.driver_cash_credit_markets_v1e') IS NOT NULL THEN bad := bad || E'\n  already exists: driver_cash_credit_markets_v1e'; END IF;
 IF to_regclass('public.cash_ride_fee_holds_v1e') IS NOT NULL THEN bad := bad || E'\n  already exists: cash_ride_fee_holds_v1e'; END IF;
 IF EXISTS (SELECT 1 FROM public.jobs WHERE metadata->>'cash_collection_mode'='full_customer_charge') THEN bad := bad || E'\n  a job already uses cash_collection_mode=full_customer_charge'; END IF;
 IF bad <> '' THEN RAISE EXCEPTION 'PREREQ FAILED:%', bad; END IF;
 RAISE NOTICE 'PREREQ OK: % replaced functions match, % release functions absent, cash tables absent, no cash-mode jobs', 4, 11;
END $pre$;
SELECT 'payment_status values on jobs' AS check_name, coalesce(string_agg(DISTINCT coalesce(payment_status,'<null>'), ', '),'none') AS found FROM public.jobs;
ROLLBACK;
